import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import {
  createTestContext,
  recordEvent,
  replayEvents,
  getDatabase,
  type HiveContext,
} from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}

describe('event-store confidence validation', () => {
  it('does not durably record a non-numeric confidence as a null value', async () => {
    const { ctx } = await bootstrap();

    // Record an add event whose confidence is NaN. recordEvent writes
    // `confidence: NaN` into the commit body with no numeric validation.
    const id = await recordEvent(
      ctx,
      { type: 'add', nodeType: 'goal', content: 'x', confidence: NaN },
      branch,
    );

    // Rebuild the materialized view from the git log.
    await replayEvents(ctx, branch, true);

    const db = getDatabase(ctx);
    const row = db
      .prepare('SELECT metadata_json FROM nodes WHERE change_id = ?')
      .get(id) as { metadata_json?: string } | undefined;
    const meta = row && row.metadata_json ? JSON.parse(row.metadata_json) : {};

    // A confidence that could not be expressed numerically must NOT be
    // silently persisted as a null the schema cannot mean.
    expect(meta.confidence).not.toBeNull();
  });
});
